<?php
require_once __DIR__.'/../../includes/staff/auth.php';require_permission('salary.manage');verify_csrf();$pdo=staff_db();$me=current_staff();
if($_SERVER['REQUEST_METHOD']==='POST'){$basic=(float)$_POST['basic_salary'];$ot=(float)$_POST['overtime_amount'];$allow=(float)$_POST['allowance_amount'];$comm=(float)$_POST['commission_amount'];$bonus=(float)$_POST['bonus_amount'];$ded=(float)$_POST['deduction_amount'];$adv=(float)$_POST['advance_deduction'];$net=$basic+$ot+$allow+$comm+$bonus-$ded-$adv;$s=$pdo->prepare("INSERT INTO salary_records(staff_id,salary_month,salary_year,basic_salary,overtime_amount,allowance_amount,commission_amount,bonus_amount,deduction_amount,advance_deduction,net_salary,notes,payment_status,payment_date,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE basic_salary=VALUES(basic_salary),overtime_amount=VALUES(overtime_amount),allowance_amount=VALUES(allowance_amount),commission_amount=VALUES(commission_amount),bonus_amount=VALUES(bonus_amount),deduction_amount=VALUES(deduction_amount),advance_deduction=VALUES(advance_deduction),net_salary=VALUES(net_salary),notes=VALUES(notes),payment_status=VALUES(payment_status),payment_date=VALUES(payment_date)");$s->execute([$_POST['staff_id'],$_POST['salary_month'],$_POST['salary_year'],$basic,$ot,$allow,$comm,$bonus,$ded,$adv,$net,trim($_POST['notes']),$_POST['payment_status'],$_POST['payment_date']?:null,$me['id']]);staff_redirect('staff/admin/payroll.php');}
$staff=$pdo->query("SELECT id,first_name,last_name FROM staff WHERE is_active=1 ORDER BY first_name")->fetchAll();$rows=$pdo->query("SELECT sr.*,CONCAT(s.first_name,' ',COALESCE(s.last_name,'')) staff_name FROM salary_records sr JOIN staff s ON s.id=sr.staff_id ORDER BY salary_year DESC,salary_month DESC")->fetchAll();$pageTitle='Payroll';require __DIR__.'/../../includes/staff/header.php';?>
<main class="staff-content"><div class="page-head"><div><p class="eyebrow">Boss / Admin</p><h1>Payroll</h1></div></div><details class="staff-panel form-details"><summary>Create / update salary record</summary><form method="post" class="form-grid"><?= csrf_field() ?><label>Staff<select name="staff_id"><?php foreach($staff as $s):?><option value="<?= $s['id'] ?>"><?= h(trim($s['first_name'].' '.$s['last_name'])) ?></option><?php endforeach;?></select></label><label>Month<input type="number" name="salary_month" min="1" max="12" value="<?= date('n') ?>"></label><label>Year<input type="number" name="salary_year" value="<?= date('Y') ?>"></label><label>Basic<input type="number" step=".01" name="basic_salary" value="0"></label><label>Overtime<input type="number" step=".01" name="overtime_amount" value="0"></label><label>Allowance<input type="number" step=".01" name="allowance_amount" value="0"></label><label>Commission<input type="number" step=".01" name="commission_amount" value="0"></label><label>Bonus<input type="number" step=".01" name="bonus_amount" value="0"></label><label>Deductions<input type="number" step=".01" name="deduction_amount" value="0"></label><label>Advance deduction<input type="number" step=".01" name="advance_deduction" value="0"></label><label>Status<select name="payment_status"><option>draft</option><option>approved</option><option>paid</option></select></label><label>Payment date<input type="date" name="payment_date"></label><label class="span-2">Notes<textarea name="notes"></textarea></label><button class="btn primary">Save</button></form></details><section class="staff-panel table-panel"><table><thead><tr><th>Staff</th><th>Period</th><th>Basic</th><th>Net</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?= h($r['staff_name']) ?></td><td><?= h(date('M',mktime(0,0,0,$r['salary_month'],1)).' '.$r['salary_year']) ?></td><td><?= money($r['basic_salary']) ?></td><td><?= money($r['net_salary']) ?></td><td><?= h($r['payment_status']) ?></td></tr><?php endforeach;?></tbody></table></section></main><?php require __DIR__.'/../../includes/staff/footer.php';?>
